import sympy
for n in range(2, 101):
    v = n*n + n + 41
    if not sympy.isprime(v):
        print('反例: n =', n, '-> 值 =', v, '=', sympy.factorint(v))
        print('VERDICT: REFUTED')
        break
else:
    print('VERDICT: PARTIAL')

