import networkx as nx
for n in range(4, 10):
    G = nx.complete_graph(n)
    m = nx.max_weight_matching(G)
    if 2 * len(m) != n:
        print('反例: K_%d 有 %d 个顶点, 最大匹配只覆盖 %d 个, 不存在完美匹配' % (n, n, 2 * len(m)))
        print('VERDICT: REFUTED')
        break
else:
    print('VERDICT: PARTIAL')

import networkx as nx
bad = []
for n in range(2, 9):
    for G in nx.nonisomorphic_trees(n):
        if not nx.is_bipartite(G):
            bad.append(n)
            break
if bad:
    print('找到非二部树的反例, n =', bad[0])
    print('VERDICT: REFUTED')
else:
    print('n<=8 的全部非同构树均为二部图 —— 有限穷尽检查, 不构成全称证明')
    print('VERDICT: PARTIAL')
